<script>
document.addEventListener('DOMContentLoaded',function(){
const customer=document.getElementById('asset-customer-select'),site=document.getElementById('asset-site-select'),parent=document.getElementById('asset-parent-select');
if(customer&&site){const siteOptions=Array.from(site.options).filter(o=>o.value),parentOptions=parent?Array.from(parent.options).filter(o=>o.value):[];const filterRelations=()=>{const c=customer.value,s=site.value;let siteSelected=false;siteOptions.forEach(o=>{const match=c!==''&&o.dataset.customerId===c;o.hidden=!match;o.disabled=!match;if(match&&o.selected)siteSelected=true});if(!siteSelected)site.value='';site.disabled=c==='';site.options[0].textContent=c===''?'Select customer first':'Select site';if(parent){let parentSelected=false;parentOptions.forEach(o=>{const match=c!==''&&site.value!==''&&o.dataset.customerId===c&&o.dataset.siteId===site.value;o.hidden=!match;o.disabled=!match;if(match&&o.selected)parentSelected=true});if(!parentSelected)parent.value='';parent.disabled=!(c&&site.value)}};customer.addEventListener('change',filterRelations);site.addEventListener('change',filterRelations);filterRelations()}
const template=document.getElementById('asset-template-select'),specWrap=document.getElementById('dynamic-spec-fields'),specEmpty=document.getElementById('dynamic-spec-empty'),specJson=document.getElementById('technical-specifications-json');let oldSpecs={};try{oldSpecs=specJson&&specJson.value?JSON.parse(specJson.value):{}}catch(e){}
const renderSpecs=()=>{if(!template||!specWrap||!specJson)return;specWrap.innerHTML='';const opt=template.options[template.selectedIndex];let schema={};try{schema=opt&&opt.dataset.schema?JSON.parse(opt.dataset.schema):{}}catch(e){};const entries=Object.entries(schema||{});specEmpty.style.display=entries.length?'none':'block';entries.forEach(([key,definition])=>{const def=(definition&&typeof definition==='object')?definition:{};const label=def.label||key.replaceAll('_',' ');const box=document.createElement('div');box.className='field';const lab=document.createElement('label');lab.textContent=label;const input=document.createElement('input');input.type=def.type==='number'?'number':'text';input.dataset.specKey=key;input.value=oldSpecs[key]??'';if(def.unit)input.placeholder=def.unit;input.addEventListener('input',syncSpecs);box.append(lab,input);specWrap.append(box)});syncSpecs()};const syncSpecs=()=>{if(!specWrap||!specJson)return;const data={};specWrap.querySelectorAll('[data-spec-key]').forEach(i=>{if(i.value!=='')data[i.dataset.specKey]=i.type==='number'&&i.value!==''?Number(i.value):i.value});specJson.value=Object.keys(data).length?JSON.stringify(data):''};if(template){template.addEventListener('change',()=>{oldSpecs={};renderSpecs()});renderSpecs()}
const search=document.getElementById('registry-search'),status=document.getElementById('registry-status'),criticality=document.getElementById('registry-criticality'),cards=Array.from(document.querySelectorAll('#asset-registry-list .asset'));const filterRegistry=()=>{const q=(search?.value||'').toLowerCase(),s=status?.value||'',c=criticality?.value||'';cards.forEach(card=>{const ok=(!q||card.dataset.search.includes(q))&&(!s||card.dataset.status===s)&&(!c||card.dataset.criticality===c);card.style.display=ok?'flex':'none'})};[search,status,criticality].forEach(el=>el&&el.addEventListener(el.tagName==='INPUT'?'input':'change',filterRegistry));
});
</script>
